 *
 * @return ASTNode?
 */
fun ASTNode.prevNodeUntilNode(stopNodeType: IElementType, checkNodeType: IElementType): ASTNode? =
    siblings(false).takeWhile { it.elementType != stopNodeType }.find { it.elementType == checkNodeType }

/**
