                                      excludeChildrenCondition: ((ASTNode) -> Boolean) = { false },
                                      condition: (ASTNode) -> Boolean,
): List<ASTNode> {
    val result = if (condition(this) && withSelf) mutableListOf(this) else mutableListOf()
    return result + this.getChildren(null)
